<?php
declare(strict_types=1); require_once __DIR__.'/../app/bootstrap.php'; require_admin(); $pdo=db();$edit=null;
if(isset($_GET['edit'])){$s=$pdo->prepare('SELECT * FROM categories WHERE id=?');$s->execute([(int)$_GET['edit']]);$edit=$s->fetch()?:null;}
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();try{$action=$_POST['action']??'';if($action==='save'){$id=(int)($_POST['id']??0);$name=trim((string)($_POST['name']??''));$slug=trim((string)($_POST['slug']??''));if($slug==='')$slug=strtolower(trim(preg_replace('/[^a-zA-Z0-9]+/','-',iconv('UTF-8','ASCII//TRANSLIT',$name)?:$name),'-'));if($name==='')throw new RuntimeException();$desc=trim((string)($_POST['description']??''));$active=isset($_POST['active'])?1:0;if($id){$pdo->prepare('UPDATE categories SET name=?,slug=?,description=?,active=? WHERE id=?')->execute([$name,$slug,$desc,$active,$id]);flash('Categoria atualizada.');}else{$pdo->prepare('INSERT INTO categories(name,slug,description,active) VALUES(?,?,?,?)')->execute([$name,$slug,$desc,$active]);flash('Categoria criada.');}redirect('categories.php');}if($action==='delete'){$id=(int)$_POST['id'];$s=$pdo->prepare('SELECT COUNT(*) FROM products WHERE category_id=?');$s->execute([$id]);if((int)$s->fetchColumn()>0){$pdo->prepare('UPDATE categories SET active=0 WHERE id=?')->execute([$id]);flash('A categoria tem produtos associados e foi desativada.');}else{$pdo->prepare('DELETE FROM categories WHERE id=?')->execute([$id]);flash('Categoria eliminada.');}redirect('categories.php');}}catch(Throwable $e){flash('Não foi possível guardar. Verifique se o nome/slug já existe.','error');redirect('categories.php');}}
$rows=$pdo->query('SELECT c.*,COUNT(p.id) product_count FROM categories c LEFT JOIN products p ON p.category_id=c.id GROUP BY c.id ORDER BY c.id DESC')->fetchAll();layout_start('Categorias');echo '<section class="panel"><h2>'.($edit?'Editar categoria':'Nova categoria').'</h2><form method="post">'.csrf_field().'<input type="hidden" name="action" value="save"><input type="hidden" name="id" value="'.(int)($edit['id']??0).'"><div class="form-grid"><div class="field"><label>Nome</label><input name="name" required value="'.e($edit['name']??'').'"></div><div class="field"><label>Slug</label><input name="slug" value="'.e($edit['slug']??'').'" placeholder="gerado automaticamente se vazio"></div><div class="field"><label>Estado</label><label><input style="width:auto" type="checkbox" name="active" value="1"'.((int)($edit['active']??1)===1?' checked':'').'> Ativa</label></div></div><div class="field"><label>Descrição</label><textarea name="description" rows="3">'.e($edit['description']??'').'</textarea></div><div class="form-actions"><button>Guardar categoria</button>'.($edit?'<a class="btn secondary" href="categories.php">Cancelar</a>':'').'</div></form></section><section class="panel"><h2>Categorias existentes</h2><div class="table-wrap"><table><thead><tr><th>Nome</th><th>Slug</th><th>Produtos</th><th>Estado</th><th>Ações</th></tr></thead><tbody>';if(!$rows)echo '<tr><td colspan="5" class="empty">Ainda não existem categorias.</td></tr>';foreach($rows as $r)echo '<tr><td>'.e($r['name']).'</td><td>'.e($r['slug']).'</td><td>'.(int)$r['product_count'].'</td><td><span class="badge">'.((int)$r['active']?'Ativa':'Inativa').'</span></td><td><div class="actions"><a class="btn small secondary" href="categories.php?edit='.(int)$r['id'].'">Editar</a><form method="post" onsubmit="return confirm(\'Eliminar/desativar categoria?\')">'.csrf_field().'<input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="'.(int)$r['id'].'"><button class="danger small">Eliminar</button></form></div></td></tr>';echo '</tbody></table></div></section>';layout_end();
